public int search(int[] nums, int target) {
    int left = 0, right = nums.length - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (nums[mid] == target) return mid;
        if (nums[left] <= nums[mid]) { // Left half is sorted
            if (nums[left] <= target && target < nums[mid]) right = mid - 1;
            else left = mid + 1;
        } else { // Right half is sorted
            if (nums[mid] < target && target <= nums[right]) left = mid + 1;
            else right = mid - 1;
        }
    }
    return -1;
}

public boolean searchMatrix(int[][] matrix, int target) {
    int m = matrix.length, n = matrix[0].length;
    int row = 0, col = n - 1; // Start top-right
    while (row < m && col >= 0) {
        if (matrix[row][col] == target) return true;
        else if (matrix[row][col] > target) col--; // Move left
        else row++; // Move down
    }
    return false;
}

public int minSubArrayLen(int target, int[] nums) {
    int n = nums.length;
    int[] prefix = new int[n + 1];
    for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + nums[i];

    int left = 1, right = n, ans = 0;
    while (left <= right) {
        int mid = left + (right - left) / 2; // Length of subarray
        boolean found = false;
        for (int i = mid; i <= n; i++) {
            if (prefix[i] - prefix[i - mid] >= target) found = true;
        }
        if (found) {
            ans = mid;
            right = mid - 1; // Try smaller length
        } else {
            left = mid + 1;
        }
    }
    return ans;
}

// e.g., Capacity To Ship Packages Within D Days
public int shipWithinDays(int[] weights, int days) {
    int low = 0, high = 0;
    for (int w : weights) {
        low = Math.max(low, w);
        high += w;
    }
    while (low < high) {
        int mid = low + (high - low) / 2;
        if (canShip(weights, days, mid)) {
            high = mid;
        } else {
            low = mid + 1;
        }
    }
    return low;
}

private boolean canShip(int[] w, int days, int cap) {
    int currentLoad = 0, requiredDays = 1;
    for (int weight : w) {
        if (currentLoad + weight > cap) {
            requiredDays++;
            currentLoad = 0;
        }
        currentLoad += weight;
    }
    return requiredDays <= days;
}

// Find K-th Smallest Pair Distance
public int smallestDistancePair(int[] nums, int k) {
    Arrays.sort(nums);
    int low = 0, high = nums[nums.length - 1] - nums[0];
    while (low < high) {
        int mid = low + (high - low) / 2;
        int count = 0, left = 0;
        for (int right = 0; right < nums.length; right++) {
            while (nums[right] - nums[left] > mid) left++;
            count += right - left;
        }
        if (count < k) low = mid + 1;
        else high = mid;
    }
    return low;
}

